import argparse
import logging
import subprocess
import sys
import re
import os


GIT_VERSION_COMMAND = ["git", "describe", "--tags", "--long", "--dirty", "--always", "--match", "v[0-9]*"]

# A release's tag is vX.Y.Z (ADR-004, gate 3); an older one of two numbers, vX.Y, counts as X.Y.0
GIT_VERSION_PATTERN_REGEX = (r'v(?P<major>\d+)\.(?P<minor>\d+)(?:\.(?P<patch>\d+))?-(?P<commits>\d+)'
                             r'-g(?P<short_hash>[a-f0-9]+)(?P<dirty>-dirty)?$')

C_HEADER_TEMPLATE = """// ---------------------------------------------------------- //
// This file is autogenerated by gen_version.py; do not edit! //
// ---------------------------------------------------------- //

#ifndef {capitalized_filename}_H_
#define {capitalized_filename}_H_

// Implemented in version.c
extern const char * version_string;
extern const char * vcs_hash;
extern const char * build_type;

#endif  //  {capitalized_filename}_H_
"""

C_SOURCE_TEMPLATE = """// ---------------------------------------------------------- //
// This file is autogenerated by gen_version.py; do not edit! //
// ---------------------------------------------------------- //

#include "version.h"

const char * version_string = "{version_string}";
const char * vcs_hash = "{hash_string}";
const char * build_type = "{build_type}";
"""


def read_version():
    """
    The build's version, from git.

    Returns:
        The regex match of `git describe` (major, minor, patch, short_hash, dirty), or None when it is not a version.
    """
    # git is asked in this script's folder, inside the repository, not in the build's: a build folder outside the
    # repository has no git to ask (ADR-011)
    output = subprocess.check_output(GIT_VERSION_COMMAND, text=True, cwd=os.path.dirname(os.path.abspath(__file__)))
    logging.debug(f'Raw output: {output}')
    return re.match(GIT_VERSION_PATTERN_REGEX, output.strip())


def version_numbers(match):
    """
    The numbers of a version read from git.

    Args:
        match: read_version()'s match.

    Returns:
        (major, minor, patch, commits since the tag).
    """
    return (int(match.group("major")), int(match.group("minor")), int(match.group("patch") or 0),
            int(match.group("commits")))


def version_text(match):
    """
    The firmware's version as the unit shows it: X.Y.Z at a tag, X.Y.Z-N a build N commits after it, -dirty when the
    tree had changes.

    Args:
        match: read_version()'s match.

    Returns:
        The text.
    """
    major, minor, patch, commits = version_numbers(match)
    return f"{major}.{minor}.{patch}{f'-{commits}' if commits else ''}{match.group('dirty') or ''}"


def block_text(first, second):
    """
    A metadata block's version as text, as the firmware writes it (`running.block`) and as version_text writes the
    version it came from: (512, 256) is 2.0.1, (276, 218) is 1.20.0-218.

    Args:
        first: the block's first number, X x 256 + Y.
        second: its second, Z x 256 + N.

    Returns:
        The text.
    """
    commits = second & 0xFF
    return f"{first >> 8}.{first & 0xFF}.{second >> 8}{f'-{commits}' if commits else ''}"


def block_version():
    """
    The version for the image's metadata block (ADR-004): two 16-bit numbers, the release as X x 256 + Y and then
    Z x 256 + N, N the commits since the tag held at 255. A release orders after every build before it, and every
    build after a tag after the tag.

    Returns:
        "first;second", a CMake list; "" when git gives no version.
    """
    match = read_version()
    if not match:
        return ""
    major, minor, patch, commits = version_numbers(match)
    if minor > 255 or major * 256 + minor > 0xFFFF or patch > 255:
        raise ValueError(f"{major}.{minor}.{patch} does not fit the metadata block's version")
    return f"{major * 256 + minor};{patch * 256 + min(commits, 255)}"


def main(output_path, build_type):
    match = read_version()

    version_string = "unknown"
    hash_string = ""

    if match:
        version_string = version_text(match)
        hash_string = match.group('short_hash')

    c_header_string = C_HEADER_TEMPLATE.format(
        capitalized_filename="VERSION")
    logging.debug(f"c_header_string={c_header_string}")

    c_source_string = C_SOURCE_TEMPLATE.format(
        capitalized_filename="VERSION", version_string=version_string, hash_string=hash_string, build_type=build_type)
    logging.debug(f"c_header_string={c_source_string}")

    
    c_header_filepath = os.path.join(output_path, "version.h")
    with open(c_header_filepath, "w") as fp:
        logging.debug(f"Write to {c_header_filepath}")
        fp.write(c_header_string)

    c_source_filepath = os.path.join(output_path, "version.c")
    with open(c_source_filepath, "w") as fp:
        logging.debug(f"Write to {c_source_filepath}")
        fp.write(c_source_string)


if __name__ == "__main__":
    parser = argparse.ArgumentParser()

    parser.add_argument('-o', '--output_filepath', help="The output filepath that the C header will be written to")
    parser.add_argument('--build-type', help="CMake build type")
    parser.add_argument('--block-version', action='store_true',
                        help="Print the metadata block's version (ADR-004) as a CMake list, and write nothing")
    parser.add_argument('--version-string', action='store_true',
                        help="Print the firmware's version as the unit shows it, and write nothing")

    parser.add_argument('-v', '--verbose', action='count', default=0)


    args = parser.parse_args()
    if args.block_version:
        print(block_version())
        sys.exit(0)
    if args.version_string:
        found = read_version()
        print(version_text(found) if found else "unknown")
        sys.exit(0)
    if not args.output_filepath or not args.build_type:
        parser.error("-o and --build-type are required")

    logging_levels = {0: logging.ERROR,
                      1: logging.DEBUG,
                      2: logging.INFO,
                      3: logging.WARNING,
                      4: logging.ERROR,
                      5: logging.CRITICAL}
    
    logging.basicConfig(stream=sys.stdout, level=logging_levels[args.verbose])

    main(args.output_filepath, args.build_type)
